-- ============================================================
-- RECOVER reliable MANUAL scan sessions from the audit log
--   (logs_rows.sql -> MANUAL_IN / SCAN_IN / MANUAL_OUT / SCAN_OUT)
--
-- Scope:  in_date >= 2026-08-01 (after July end)  AND  closed session
--         with duration 0-48h (reliable same-shift/full-day/overnight).
--         Mis-paired >48h matches are EXCLUDED.
--
-- Marked is_manual = true (centre-pushed manual scans).
-- id is omitted so the IDENTITY column assigns fresh ids.
-- Only touches attendance_sessions (no portal tables).
-- ============================================================

-- Ensure the duty_type CHECK accepts production values.
ALTER TABLE public.attendance_sessions
  DROP CONSTRAINT IF EXISTS attendance_sessions_duty_type_check;
ALTER TABLE public.attendance_sessions
  ADD CONSTRAINT attendance_sessions_duty_type_check
  CHECK (duty_type IN ('SATSCAN','DAILY','NIGHT','WATCH_AND_WARD','JATHA'));

-- Disable the overlap trigger during this historical backfill.
-- Some recovered scans legitimately coincide with jatha records for the same
-- sewadar/date; the trigger is meant to prevent *future* conflicting writes,
-- not to reject recovered history. Re-enabled at the end.
ALTER TABLE public.attendance_sessions
  DISABLE TRIGGER trg_check_session_overlap;

-- If the above trigger is somehow missing, ensure it exists so ENABLE works.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_trigger
    WHERE tgname = 'trg_check_session_overlap'
      AND tgrelid = 'public.attendance_sessions'::regclass
  ) THEN
    CREATE TRIGGER trg_check_session_overlap
      BEFORE INSERT OR UPDATE ON public.attendance_sessions
      FOR EACH ROW
      EXECUTE FUNCTION public.check_session_overlap();
  END IF;
END $$;

ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
ON CONFLICT DO NOTHING;
;

-- Re-enable the overlap trigger now that the backfill is complete.
ALTER TABLE public.attendance_sessions
  ENABLE TRIGGER trg_check_session_overlap;

-- Verify the import.
SELECT count(*) AS attendance_sessions_total FROM public.attendance_sessions;